// UNE SEULE PLACE pour absorber les deux formes que peut prendre la sortie du
// declencheur (message nu, ou enveloppe { message }) selon la version de n8n.
const brut = $input.item.json;
const message = brut.message || brut;

if (!brut.apiBase || !brut.botToken) {
  throw new Error('Variables n8n manquantes : COMEXA_API_BASE et TELEGRAM_BOT_TOKEN (Reglages > Variables).');
}

const media = message.voice || message.audio || null;
const texte = (message.text || '').trim();
let commande = texte.startsWith('/') ? texte.split(/\s+/)[0].toLowerCase() : '';
let args = commande ? texte.slice(commande.length).trim() : texte;

// LIEN PROFOND. L invitation part par courriel sous la forme
// https://t.me/<bot>?start=wa_<corps> ; Telegram la livre comme "/start wa_XXXX".
// Sans ce branchement, l arrivee d un tiers — le seul chemin documente — ne
// declencherait que l aide. Le copier-coller du lien entier est reconnu aussi.
function extraireCode(valeur) {
  const profond = valeur.match(/wa[_-]?([A-Z2-9]{12})(?![A-Z0-9])/i);
  if (profond) return profond[1].toUpperCase();
  const prefixe = valeur.match(/\bWA[-\s]?([A-Z2-9]{4})[-\s]?([A-Z2-9]{4})[-\s]?([A-Z2-9]{4})\b/i);
  if (prefixe) return (prefixe[1] + prefixe[2] + prefixe[3]).toUpperCase();
  const tirets = valeur.match(/\b([A-Z2-9]{4}-[A-Z2-9]{4}-[A-Z2-9]{4})\b/i);
  if (tirets) return tirets[1].toUpperCase().replace(/-/g, '');
  return '';
}

const code = extraireCode(texte);
if (code && (commande === '/start' || commande === '')) {
  commande = '/autoriser';
  args = code;
} else if (code && ['/autoriser', '/accepter', '/refuser'].indexOf(commande) >= 0) {
  // Le prefixe WA et les tirets sont facultatifs cote API : on rend le corps nu.
  // Une saisie vraiment illisible tombe quand meme sur le 422 du serveur.
  args = code;
}

return { json: {
  apiBase: String(brut.apiBase).replace(/\/+$/, ''),
  botToken: String(brut.botToken),
  chatId: String(message.chat?.id ?? ''),
  fromId: String(message.from?.id ?? ''),
  username: message.from?.username || '',
  messageId: String(message.message_id ?? ''),
  text: texte,
  command: commande,
  args: args,
  isVoice: Boolean(media && media.file_id),
  fileId: media ? String(media.file_id) : '',
  mimeType: media ? String(media.mime_type || 'audio/ogg') : '',
  durationSeconds: media ? Number(media.duration || 0) : 0,
} };

const d = $input.item.json.data;
const m = $('Analyse du message').item.json;
const moteur = d.provider + (d.model ? ' · ' + d.model : '');
const langue = d.language ? 'langue : ' + d.language : 'langue detectee';

return { json: {
  botToken: m.botToken,
  chatId: m.chatId,
  text: 'Transcription (' + langue + ', ' + moteur + ') :\n\n' + d.text +
        (d.replayed ? '\n\n(deja transcrit : aucun nouvel appel au moteur)' : '') +
        '\n\nEcris ta demande en texte, ou reponds a ce message : je la traite comme un ordre ecrit.',
} };

const m = $('Analyse du message').item.json;
const d = $('Appairer WhatsApp').item.json.data;
const lignes = (d.instructions || []).map(function (l, i) { return (i + 1) + '. ' + l; }).join('\n');

return { json: {
  botToken: m.botToken,
  chatId: m.chatId,
  text: 'Etat : ' + d.status + ' (compte ' + d.ownerKind + ')\n\n' +
        'A faire maintenant :\n' + lignes + '\n\n' +
        'Puis /statut pour verifier. Retrait a tout moment : /deconnecter.\n\n' +
        'Consentement ' + d.consentVersion + ' :\n' + d.consentText,
} };

const m = $('Analyse du message').item.json;
const d = $('Appairer WhatsApp').item.json.data;

return { json: {
  botToken: m.botToken,
  chatId: m.chatId,
  text: 'Aucun QR a scanner : la session est deja dans l etat ' + d.status +
        '. /statut pour le detail, /deconnecter pour repartir de zero.',
} };

const m = $('Analyse du message').item.json;
const d = $input.item.json.data;
const c = d.consent || {};

return { json: {
  botToken: m.botToken,
  chatId: m.chatId,
  text: 'WhatsApp — ' + d.status + '\n' +
        'Compte : ' + d.ownerKind + (d.phoneNumber ? ' (' + d.phoneNumber + ')' : '') + '\n' +
        'Passerelle : ' + d.gatewayDriver + '\n' +
        'Capacites : ' + (d.grantedScopes || []).join(', ') + '\n' +
        'Consentement : ' + (c.valid ? 'valide' : 'NON valide') + ' (version ' + c.version + ')' +
        (c.expiresAt ? ', expire le ' + String(c.expiresAt).slice(0, 10) : ', sans echeance') + '\n' +
        (d.lastError ? 'Derniere erreur : ' + d.lastError : ''),
} };

const m = $('Analyse du message').item.json;

return { json: {
  botToken: m.botToken,
  chatId: m.chatId,
  text: 'Session WhatsApp revoquee : la passerelle est deconnectee et les contacts copies ont ete supprimes.\n' +
        'Un nouvel appairage demande un consentement explicite (/whatsapp).',
} };

const m = $('Analyse du message').item.json;
const corps = $input.item.json;
const liste = corps.data || [];
const total = (corps.meta && corps.meta.total) || liste.length;

if (liste.length === 0) {
  return { json: { botToken: m.botToken, chatId: m.chatId, text: 'Repertoire vide (ou jamais synchronise).' } };
}

const lignes = liste.slice(0, 25).map(function (c) {
  return '- ' + (c.name || '(sans nom)') + ' : ' + (c.phoneNumber || c.jid);
}).join('\n');

return { json: {
  botToken: m.botToken,
  chatId: m.chatId,
  text: 'Contacts WhatsApp (' + total + ' au total, 25 affiches) :\n' + lignes,
} };

const m = $('Analyse du message').item.json;
const liaison = $('Résoudre la liaison').item.json.data;
const args = m.args || '';
const sep = args.search(/\s/);

if (sep < 1) {
  return { json: {
    valide: false,
    botToken: m.botToken,
    chatId: m.chatId,
    text: 'Format attendu : /envoyer +213555123456 votre message\n' +
          'Le numero doit etre international (ou local avec le 0 initial). Les groupes sont refuses.',
  } };
}

return { json: {
  valide: true,
  apiBase: m.apiBase,
  userId: liaison.userId,
  to: args.slice(0, sep),
  body: args.slice(sep + 1).trim(),
  // Cle d idempotence PAR DEMANDE Telegram : un rejeu du workflow ne renvoie pas
  // deux fois le meme message a un client.
  idempotencyKey: ('tg-' + m.chatId + '-' + m.messageId).slice(0, 120),
  telegramChatId: m.chatId,
  telegramMessageId: m.messageId,
} };

const m = $('Analyse du message').item.json;
const d = $input.item.json.data;

return { json: {
  botToken: m.botToken,
  chatId: m.chatId,
  text: 'Message ' + d.status + ' vers ' + d.to.jid +
        (d.replayed ? '\n(deja envoye : ce rejeu n a rien transmis de plus)' : '') +
        (d.gatewayMessageId ? '\nIdentifiant WhatsApp : ' + d.gatewayMessageId : ''),
} };

const m = $('Analyse du message').item.json;
const d = $input.item.json.data;

return { json: {
  botToken: m.botToken,
  chatId: m.chatId,
  text: d.consentText + '\n\n---\n' +
        'Si tu acceptes EXACTEMENT cela, reponds : /accepter ' + m.args + '\n' +
        'Sinon : /refuser ' + m.args + '\n\n' +
        'Rien n est enregistre tant que tu n as pas repondu.',
} };

const m = $('Analyse du message').item.json;
const d = $('Accepter invitation').item.json.data;
const p = d.pairing;
const lignes = (p.instructions || []).map(function (l, i) { return (i + 1) + '. ' + l; }).join('\n');

return { json: {
  botToken: m.botToken,
  chatId: m.chatId,
  text: 'Autorisation enregistree (consentement ' + p.consentVersion +
        (p.consentExpiresAt ? ', valable jusqu au ' + String(p.consentExpiresAt).slice(0, 10) : '') + ')\n\n' +
        'Compte : ' + p.ownerKind + ' — etat ' + p.status + '\n\n' + lignes + '\n\n' +
        'Ce que tu as accepte :\n' + d.consentText + '\n\n' +
        'Retrait a tout moment : le titulaire le fait depuis l application web.',
} };

const m = $('Analyse du message').item.json;
const p = $('Accepter invitation').item.json.data.pairing;

return { json: {
  botToken: m.botToken,
  chatId: m.chatId,
  text: 'Autorisation acceptee, mais aucun QR a scanner : la session est dans l etat ' + p.status + '.',
} };

const m = $('Analyse du message').item.json;

return { json: {
  botToken: m.botToken,
  chatId: m.chatId,
  text: 'Invitation refusee : rien n a ete connecte, et le code ne peut plus etre utilise.',
} };

// n8n ne donne pas la meme forme d erreur selon la version : le code stable est
// cherche partout ou il peut se trouver, sinon extrait du texte brut.
// Les workflows doivent brancher sur error.code, jamais sur le message.
const item = $input.item.json;
const m = $('Analyse du message').item.json;
const err = item.error || item;
const corps = err.error || err.responseBody || err.body || (typeof err === 'object' ? err : null);

let code = (corps && corps.error && corps.error.code) || (corps && corps.code) || err.code || null;
const statut = err.statusCode || err.status || (corps && corps.status) || null;
let detail = (corps && corps.error && corps.error.message) || err.message || '';

if (!code) {
  const trouve = JSON.stringify(err).match(/\b(?:WHATSAPP|TRANSCRIPTION|TELEGRAM|INTEGRATION)_[A-Z_]+/);
  code = trouve ? trouve[0] : 'ERREUR_INCONNUE';
}

const MESSAGES = {
  TELEGRAM_LINK_NOT_FOUND: 'Ton compte Telegram n est pas lie a Comexa. Ouvre l application web, puis /lier dans le bot.',
  TRANSCRIPTION_NOT_CONFIGURED: 'La transcription n est pas activee cote serveur (TRANSCRIPTION_PROVIDER=none).',
  TRANSCRIPTION_AUDIO_REQUIRED: 'Je n ai recu aucun audio : le telechargement depuis Telegram a echoue.',
  TRANSCRIPTION_UNSUPPORTED_FORMAT: 'Format audio non pris en charge (une video n est pas un vocal).',
  TRANSCRIPTION_PAYLOAD_TOO_LARGE: 'Audio trop long : au-dela de la taille accepte par le serveur.',
  TRANSCRIPTION_UNAUTHORIZED: 'La cle du moteur de transcription est refusee (a corriger cote serveur).',
  TRANSCRIPTION_RATE_LIMITED: 'Le moteur de transcription est sature : reessaie dans une minute.',
  TRANSCRIPTION_UPSTREAM_UNREACHABLE: 'Le moteur de transcription ne repond pas.',
  TRANSCRIPTION_UPSTREAM_FAILED: 'Le moteur n a rendu aucun texte exploitable (silence, bruit, langue non reconnue).',
  WHATSAPP_GATEWAY_NOT_CONFIGURED: 'La passerelle WhatsApp n est pas deployee cote serveur.',
  WHATSAPP_GATEWAY_UNREACHABLE: 'La passerelle WhatsApp ne repond pas.',
  WHATSAPP_GATEWAY_UNAUTHORIZED: 'La cle de la passerelle WhatsApp est refusee (a corriger cote serveur).',
  WHATSAPP_GATEWAY_FEATURE_UNAVAILABLE: 'Cette passerelle ne fournit pas cette fonction (repertoire : licence WAHA PLUS).',
  WHATSAPP_ACCOUNT_NOT_FOUND: 'Aucun compte WhatsApp actif : /whatsapp pour l appairer.',
  WHATSAPP_SESSION_NOT_CONNECTED: 'La session n est pas appairee : /whatsapp puis scanner le QR.',
  WHATSAPP_ACCOUNT_REVOKED: 'Cette autorisation a ete retiree : /whatsapp pour la redemander.',
  WHATSAPP_CONSENT_MISSING: 'Aucun consentement enregistre : /whatsapp pour appairer.',
  WHATSAPP_CONSENT_EXPIRED: 'Le consentement a expire : le titulaire doit accepter a nouveau.',
  WHATSAPP_CONSENT_REVOKED: 'Le consentement a ete retire : aucun envoi n est possible.',
  WHATSAPP_CONSENT_OUTDATED: 'Le texte de consentement a change : une nouvelle acceptation est necessaire.',
  WHATSAPP_SCOPE_NOT_GRANTED: 'Cette capacite n a pas ete accordee au moment du consentement.',
  WHATSAPP_RECIPIENT_INVALID: 'Destinataire illisible. Format : /envoyer +213555123456 message',
  WHATSAPP_GROUP_NOT_ALLOWED: 'L envoi vers un groupe est refuse : ecris aux personnes une par une.',
  WHATSAPP_BODY_EMPTY: 'Message vide.',
  WHATSAPP_BODY_TOO_LONG: 'Message trop long : le raccourcir (il n est jamais tronque).',
  WHATSAPP_RATE_LIMITED: 'Plafond d envois atteint pour ce compte : attendre la fin de l heure glissante.',
  WHATSAPP_CODE_INVALID: 'Code d autorisation invalide, deja utilise ou expire.',
  VALIDATION_ERROR: 'Requete refusee par le serveur : ' + detail,
};

return { json: {
  botToken: m.botToken,
  chatId: m.chatId,
  text: (MESSAGES[code] || 'Echec (' + code + ')' + (detail ? ' : ' + detail : '')) +
        (statut ? ' [HTTP ' + statut + ']' : ''),
} };
